'use strict';const slides=LESSON.slides;let current=Math.min(slides.length-1,Math.max(0,(Number(location.hash.slice(1))||1)-1)),ch;const el=id=>document.getElementById(id);slides.forEach((s,i)=>{const o=document.createElement('option');o.value=i;o.textContent=`${i+1}. ${s.title}`;el('select').append(o)});function render(){const s=slides[current],start=slides.slice(0,current).filter(s=>!s.extra).reduce((a,s)=>a+s.minutes,0);el('title').textContent=s.title;el('notes').textContent=s.notes;el('question').textContent=s.question;el('answer').textContent=s.answer;el('timing').textContent=`第 ${current+1} / ${slides.length} 页 · 本页 ${s.minutes} 分钟 · ${s.extra?'备用':`主线建议 ${start}—${start+s.minutes} 分钟`}`;el('select').value=current}function go(n){current=Math.max(0,Math.min(slides.length-1,n));ch?.postMessage({type:'goto',page:current});render()}try{ch=new BroadcastChannel('classroom-db-lesson01');ch.onmessage=e=>{if(e.data.type==='slide'){current=e.data.page;render()}};ch.postMessage({type:'request'})}catch{}window.addEventListener('storage',e=>{if(e.key==='classroom-current-page'){current=+e.newValue;render()}});el('prev').onclick=()=>go(current-1);el('next').onclick=()=>go(current+1);el('select').onchange=()=>go(+el('select').value);render();
